def check_T(m):
    """Checks if the target sum T = m(m+1)/6 is an integer."""
    if m <= 0:
        return False
    return (m * (m + 1)) % 6 == 0

# Check small values of m
for m in range(1, 16):
    is_integer = check_T(m)
    if is_integer:
        T = (m * (m + 1)) // 6
        print(f"m={m}: T={T}, T is integer.")
    else:
        print(f"m={m}: T is not integer.")

